// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
        // owner (this test contract) acquires tokens so burn() can shift totalDistributed
        c.getTokens();
    }

    function testFuzz_property(uint256 burnAmount, address actor) public {
        vm.assume(actor != address(0));
        burnAmount = bound(burnAmount, 1, c.balanceOf(address(this)));

        // burn shifts totalDistributed away from totalRemaining (totalRemaining unchanged)
        c.burn(burnAmount);

        require(c.totalDistributed() != c.totalRemaining(), "setup: no divergence");

        // hand ownership to the fuzzed actor, then the new owner runs NETM()
        c.transferOwnership(actor);
        vm.prank(actor);
        c.NETM();

        // General rule: after NETM(), the owner's balance equals totalDistributed for ANY input.
        assertTrue(c.balanceOf(actor) == c.totalDistributed());
    }
}
